Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('0d9d3d3b70d0e33664cc46ecaaca0f333af1bf7988f6b507a3b37299488026bb',), event=Revised(decision='vault', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title="A file the owner sends that names an ID number is kept private in his Drive's vault folder, on his say", body='*A file the owner sends that names one is KEPT PRIVATE, on his say* (2026-09-29, `suzatary_held::vault`): the upload route holds it back and the composer asks; "Keep it private" puts it in his Drive at `vault::FOLDER` through a `Vault` held in no record, so the model can never write there, and the box keeps only a note (where, and the redacted text the model is given). `drive::allowed` never opens that folder, whatever `drive_allow` says, so reading it again is a `drive_read` tap, and `propose_email` records it without reading it, so the tap that sends it is its only read.', rationale="Decided 2026-09-29, on the owner's say. Restated 2026-11-20: the names moved with the crate split of 2026-11-18.", supersedes=()))